create table public.queuehub_order_qr_tokens(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.queuehub_restaurants(id) on delete cascade,queue_session_id uuid not null references public.queuehub_queue_sessions(id) on delete cascade,ticket_number integer not null check(ticket_number>0),token_hash text not null unique,expires_at timestamptz not null,first_redeemed_at timestamptz,last_redeemed_at timestamptz,redemption_count integer not null default 0 check(redemption_count>=0),issued_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),revoked_at timestamptz,check(expires_at>created_at));
create index queuehub_order_qr_restaurant_session_idx on public.queuehub_order_qr_tokens(restaurant_id,queue_session_id);create index queuehub_order_qr_expires_idx on public.queuehub_order_qr_tokens(expires_at);create index queuehub_order_qr_issued_by_idx on public.queuehub_order_qr_tokens(issued_by);alter table public.queuehub_order_qr_tokens enable row level security;revoke all on public.queuehub_order_qr_tokens from public,anon,authenticated;
create or replace function public.queuehub_issue_order_qr_service(p_actor_user_id uuid,p_restaurant_id uuid,p_ticket_number integer,p_token_hash text,p_expires_at timestamptz)returns jsonb language plpgsql security definer set search_path=public as $$ declare v_venue_id uuid;v_role text;v_session_id uuid;v_id uuid;begin if p_actor_user_id is null then raise exception 'actor required' using errcode='22023';end if;if p_ticket_number is null or p_ticket_number<=0 then raise exception 'invalid ticket number' using errcode='22023';end if;if p_token_hash is null or length(p_token_hash)<>64 then raise exception 'invalid token hash' using errcode='22023';end if;if p_expires_at is null or p_expires_at<=now() or p_expires_at>now()+interval '2 days' then raise exception 'invalid expiry' using errcode='22023';end if;select venue_id into v_venue_id from public.queuehub_restaurants where id=p_restaurant_id and is_active=true;if v_venue_id is null then raise exception 'restaurant not found' using errcode='P0002';end if;select role into v_role from public.queuehub_staff_members where user_id=p_actor_user_id and venue_id=v_venue_id and is_active=true;if v_role not in('operator','manager','admin')then raise exception 'insufficient QR issue permission' using errcode='42501';end if;select qs.id into v_session_id from public.queuehub_queue_status st join public.queuehub_queue_sessions qs on qs.id=st.queue_session_id where st.restaurant_id=p_restaurant_id;if v_session_id is null then raise exception 'queue session not found' using errcode='P0002';end if;insert into public.queuehub_order_qr_tokens(restaurant_id,queue_session_id,ticket_number,token_hash,expires_at,issued_by)values(p_restaurant_id,v_session_id,p_ticket_number,lower(p_token_hash),p_expires_at,p_actor_user_id)returning id into v_id;return jsonb_build_object('ok',true,'token_id',v_id,'restaurant_id',p_restaurant_id,'queue_session_id',v_session_id,'ticket_number',p_ticket_number,'expires_at',p_expires_at);end;$$;
create or replace function public.queuehub_redeem_order_qr_service(p_token_hash text)returns jsonb language plpgsql security definer set search_path=public as $$ declare v_token public.queuehub_order_qr_tokens%rowtype;v_restaurant public.queuehub_restaurants%rowtype;begin if p_token_hash is null or length(p_token_hash)<>64 then return jsonb_build_object('ok',false,'reason','invalid_token');end if;select * into v_token from public.queuehub_order_qr_tokens where token_hash=lower(p_token_hash) for update;if not found then return jsonb_build_object('ok',false,'reason','not_found');end if;if v_token.revoked_at is not null then return jsonb_build_object('ok',false,'reason','revoked');end if;if v_token.expires_at<=now() then return jsonb_build_object('ok',false,'reason','expired');end if;select * into v_restaurant from public.queuehub_restaurants where id=v_token.restaurant_id and is_active=true;if not found then return jsonb_build_object('ok',false,'reason','restaurant_unavailable');end if;update public.queuehub_order_qr_tokens set first_redeemed_at=coalesce(first_redeemed_at,now()),last_redeemed_at=now(),redemption_count=redemption_count+1 where id=v_token.id;return jsonb_build_object('ok',true,'restaurant_slug',v_restaurant.slug,'queue_session_id',v_token.queue_session_id,'ticket_number',v_token.ticket_number,'expires_at',v_token.expires_at);end;$$;
revoke all on function public.queuehub_issue_order_qr_service(uuid,uuid,integer,text,timestamptz) from public,anon,authenticated;revoke all on function public.queuehub_redeem_order_qr_service(text) from public,anon,authenticated;grant execute on function public.queuehub_issue_order_qr_service(uuid,uuid,integer,text,timestamptz) to service_role;grant execute on function public.queuehub_redeem_order_qr_service(text) to service_role;
